          <div class="comment-author-line"><strong>${escapeHtml(t.author)}</strong>${t.writerReply?"<span>Writer</span>":""}${t.pinned?`<span>${icon("bookmark",12)}Pinned</span>`:""}<small>${new Date(t.createdAt).toLocaleDateString("en-IN",{day:"numeric",month:"short"})}${t.editedAt?" \xB7 Edited":""}</small></div>
